import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Main {
    public static void main(String[] args) throws Exception {
        ExecutorService 池子 = Executors.newFixedThreadPool(2);
        Future<Integer> 甲 = 池子.submit(() -> 10 - 3);
        Future<Integer> 乙 = 池子.submit(() -> 4 * 4);
        System.out.println(甲.get());
        System.out.println(乙.get());
        池子.shutdown();
    }
}

import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class Main {
    public static void main(String[] args) {
        ThreadPoolExecutor 池子 = new ThreadPoolExecutor(
                1, 3, 10L, TimeUnit.SECONDS,
                new LinkedBlockingQueue<>());
        System.out.println("常驻 " + 池子.getCorePoolSize());
        System.out.println("上限 " + 池子.getMaximumPoolSize());
        池子.shutdown();
    }
}
